const VALIDATOR = (() => {




const GENERIC_BOOSTERS = [
  'stunning', 'epic', 'masterpiece', '8K', 'amazing',
  'cinematic', 'beautiful', 'incredible', 'perfect',
  '震撼', '极致', '完美', '史诗级', '惊艳', '大师级',
];

function validateStructuredInput(contractId, input) {
  const issues = [];
  const warnings = [];

  const contract = CONTRACTS[contractId];
  if (!contract) {
    issues.push({ level: 'error', field: 'contract', message: `未知契约: ${contractId}` });
    return { valid: false, issues, warnings };
  }

  const rules = VALIDATION_RULES[contractId] || [];

  for (const section of contract.requiredSections) {
    if (!input[section] && !hasNestedField(input, section)) {
      issues.push({ level: 'error', field: section, message: `缺少必需字段: ${section}` });
    }
  }

  for (const rule of rules) {
    const value = input[rule.field];
    if (rule.minLength && (!value || String(value).length < rule.minLength)) {
      issues.push({ level: 'error', field: rule.field, message: rule.message });
    }
    if (rule.minItems && (!Array.isArray(value) || value.length < rule.minItems)) {
      issues.push({ level: 'error', field: rule.field, message: rule.message });
    }
    if (rule.required && !value) {
      issues.push({ level: 'error', field: rule.field, message: rule.message });
    }
  }

  const fullText = JSON.stringify(input);
  for (const booster of GENERIC_BOOSTERS) {
    if (fullText.toLowerCase().includes(booster.toLowerCase())) {
      warnings.push({
        level: 'warning',
        field: 'global',
        message: `建议移除泛化美化词 "${booster}"，改为具体的视觉指令`,
      });
    }
  }

  if (Array.isArray(input.timeline) && input.timeline.length > 0) {
    let lastEnd = '0';
    for (let i = 0; i < input.timeline.length; i++) {
      const seg = input.timeline[i];
      if (seg.start && lastEnd !== seg.start) {
        warnings.push({
          level: 'warning',
          field: `timeline[${i}].start`,
          message: `时间轴分段 ${i} 的起点 ${seg.start} 与上一段终点 ${lastEnd} 不连续`,
        });
      }
      lastEnd = seg.end || lastEnd;
    }
  }

  return {
    valid: issues.length === 0,
    issues,
    warnings,
    summary: {
      errors: issues.length,
      warnings: warnings.length,
      contractName: contract.name,
    },
  };
}

function validatePromptText(promptText, contractId) {
  const issues = [];
  const warnings = [];

  if (!promptText || promptText.trim().length === 0) {
    issues.push({ level: 'error', field: 'prompt', message: '提示词为空' });
    return { valid: false, issues, warnings };
  }

  for (const booster of GENERIC_BOOSTERS) {
    const regex = new RegExp(booster, 'i');
    if (regex.test(promptText)) {
      warnings.push({
        level: 'warning',
        field: 'text',
        message: `检测到泛化美化词 "${booster}"，建议改为具体视觉指令`,
      });
    }
  }

  const contract = CONTRACTS[contractId];
  if (contract && contract.id === 'standard') {
    const expectedSections = ['素材说明', '一句话概述', '时间轴', '全局补充'];
    for (const section of expectedSections) {
      if (!promptText.includes(section)) {
        issues.push({
          level: 'error',
          field: 'structure',
          message: `标准生成缺少段落: ${section}`,
        });
      }
    }
  }

  if (promptText.length < 30) {
    issues.push({ level: 'error', field: 'length', message: '提示词过短，至少需要30个字符' });
  } else if (promptText.length > 3000) {
    warnings.push({
      level: 'warning',
      field: 'length',
      message: '提示词过长（>3000字符），可能影响 Seedance 2.5 的执行效果',
    });
  }

  return {
    valid: issues.length === 0,
    issues,
    warnings,
    summary: {
      errors: issues.length,
      warnings: warnings.length,
      length: promptText.length,
    },
  };
}

function hasNestedField(obj, path) {
  const parts = path.split('.');
  let current = obj;
  for (const part of parts) {
    if (current === null || current === undefined) return false;
    current = current[part];
  }
  return current !== null && current !== undefined;
}

return { validateStructuredInput, validatePromptText };
})();

const CONTEXT7 = (() => {




const CONTEXT7_BASE = 'https://context7.com/api/v1';
const CACHE_TTL_MS = 24 * 60 * 60 * 1000; // 24小时缓存

const cache = new Map();

async function fetchContext7Docs(library = 'seedance-2-5', topic = 'prompt contracts', signal) {
  const cacheKey = `${library}:${topic}`;
  const cached = cache.get(cacheKey);
  if (cached && Date.now() - cached.ts < CACHE_TTL_MS) {
    return cached.data;
  }

  const url = `${CONTEXT7_BASE}/context?library=${encodeURIComponent(library)}&topic=${encodeURIComponent(topic)}&tokens=5000`;
  try {
    const response = await fetch(url, { signal, method: 'GET' });
    if (!response.ok) {
      return { ok: false, error: `Context 7 returned ${response.status}` };
    }
    const data = await response.json();
    cache.set(cacheKey, { ts: Date.now(), data });
    return { ok: true, data };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}

async function getLatestSpecs({ topic = 'prompt contracts', signal } = {}) {
  const result = await fetchContext7Docs('seedance-2-5', topic, signal);
  if (result.ok) {
    return {
      source: 'context7',
      library: 'seedance-2-5',
      topic,
      content: result.data,
      version: SD25_VERSION,
      fetchedAt: new Date().toISOString(),
    };
  }

  return {
    source: 'embedded',
    library: 'seedance-2-5',
    topic,
    contracts: CONTRACTS,
    version: SD25_VERSION,
    fallbackReason: result.error,
    fetchedAt: new Date().toISOString(),
  };
}

async function getContractSpec(contractId, { signal } = {}) {

  const latest = await getLatestSpecs({ topic: `${contractId} contract`, signal });
  if (latest.source === 'context7') {
    return {
      source: 'context7',
      contractId,
      content: latest.content,
    };
  }

  const contract = CONTRACTS[contractId];
  if (!contract) {
    return { source: 'embedded', contractId, found: false };
  }
  return {
    source: 'embedded',
    contractId,
    found: true,
    name: contract.name,
    durationRange: contract.durationRange,
    description: contract.description,
    template: contract.template,
    requiredSections: contract.requiredSections,
    placeholder: contract.placeholder,
  };
}

return { getLatestSpecs, getContractSpec };
})();


function defineSpecsTool() {
  return harness.defineTool({
    name: "seedance25_specs",
    description: "获取 Seedance 2.5 视频生成的提示词契约规范。可通过 Context 7 实时查询最新文档，或使用内置标准库。",
    parameters: {
      type: "object",
      properties: {
        contract_id: { type: "string", enum: ["standard", "simple", "complex_30s", "ultra_long", "extension", "editing", "creative_transfer", "voice_dialogue", "green_screen", "white_model", "transition", "storyboard"], description: "要查询的契约 ID（可选，不传则列出全部）" },
        source: { type: "string", enum: ["embedded", "context7"], description: "数据源：embedded（内置契约库，最快）或 context7（通过 Context 7 MCP 实时获取最新文档）", default: "embedded" },
        topic: { type: "string", description: "Context 7 查询主题（仅当 source=context7 时有效）", default: "prompt contracts" },
      },
      required: [],
    },
    async execute({ contract_id, source, topic }) {
      try {
        const src = source || "embedded";
        const tp = topic || "prompt contracts";
        if (src === "context7") {
          const result = await CONTEXT7.getLatestSpecs({ topic: tp });
          return Object.assign({ success: true }, result);
        }
        if (!contract_id) {
          const list = Object.keys(CONTRACTS.CONTRACTS).map(function (id) { return CONTRACTS.CONTRACTS[id]; });
          return { success: true, source: "embedded", contracts: list };
        }
        const contract = CONTRACTS.CONTRACTS[contract_id];
        if (!contract) {
          return { success: false, error: "未找到契约: " + contract_id };
        }
        return { success: true, source: "embedded", contract: contract };
      } catch (err) {
        return { success: false, error: err.message };
      }
    },
  });
}

function defineGenerateTool() {
  return harness.defineTool({
    name: "seedance25_generate",
    description: "将结构化输入（主体、动作、镜头、光线、风格、声音、时间轴等）转换为符合 Seedance 2.5 标准格式的提示词文本。最终输出可直接交给 Seedance 2.5 本生视频生成。",
    parameters: {
      type: "object",
      properties: {
        contract_id: { type: "string", enum: ["standard", "simple", "complex_30s", "ultra_long", "extension", "editing", "creative_transfer", "voice_dialogue", "green_screen", "white_model", "transition", "storyboard"], description: "要使用的契约模板" },
        input: { type: "object", description: "结构化输入数据，按所选契约的必填字段填充" },
      },
      required: ["contract_id", "input"],
    },
    async execute({ contract_id, input }) {
      try {
        const result = GENERATOR.generatePrompt(contract_id, input);
        if (!result.success) return result;
        const validation = VALIDATOR.validatePromptText(result.prompt, contract_id);
        return Object.assign({}, result, { validation: validation });
      } catch (err) {
        return { success: false, error: err.message };
      }
    },
  });
}

function defineValidateTool() {
  return harness.defineTool({
    name: "seedance25_validate",
    description: "验证一个 Seedance 2.5 提示词文本是否符合标准格式规范，返回错误与警告。",
    parameters: {
      type: "object",
      properties: {
        prompt: { type: "string", description: "要验证的提示词文本" },
        contract_id: { type: "string", description: "对应的契约 ID", default: "standard" },
      },
      required: ["prompt"],
    },
    async execute({ prompt, contract_id }) {
      try {
        const cid = contract_id || "standard";
        return Object.assign({ success: true }, VALIDATOR.validatePromptText(prompt, cid));
      } catch (err) {
        return { success: false, error: err.message };
      }
    },
  });
}

const _tools = [];
_tools.push(defineSpecsTool());
_tools.push(defineGenerateTool());
_tools.push(defineValidateTool());

const disposers = [];
for (const tool of _tools) {
  disposers.push(harness.registerTool(ctx, tool));
}

return {
  inject: ["harness"],
  apply(applyCtx) {
    applyCtx.effect(function () {
      return function () {
        for (const d of disposers) {
          try { d(); } catch (e) {}
        }
      };
    });
    console.log("[foxai_sd25_video] 已注册 3 个 Seedance 2.5 工具到 Host");
  },
};

