          while (cur[m[1]].length <= parseInt(m[2], 10)) {
            const isLast = (i === parts.length - 2);
            const lastKey = parts[parts.length - 1];
            const lastMatch = lastKey.match(/^(\w+)\[(\d+)\]$/);
            cur[m[1]].push((m[1] === "timeline" || (lastMatch && lastMatch[1] === "timeline")) ? {} : {});
          }
          cur = cur[m[1]][parseInt(m[2], 10)];
        } else {
